from lib import *
S = SS('n47')
steps = [
    step("进程内实验(handler 500 ms,100 ms 时调用 Shutdown,ctx 2 s):Shutdown 一调用就关掉监听,之后的新请求立刻 connection refused(154 ms);在途请求照常完成,503 ms 拿到 200 slow done;但 Shutdown 本身 650 ms 才返回——它每隔一段时间轮询“是否所有连接都空闲了”,轮询间隔从 1 ms 起每次翻倍、最长 500 ms(net/http 的 Shutdown 实现 pollIntervalBase 到 shutdownPollIntervalMax),所以在最后一个请求结束后最多再等约半秒。", t=tl(S(1)), mark=lidx(S(1), '在途请求结束', 'Shutdown 返回'), done=lidx(S(1), '调用 Shutdown', 'connection refused'), b=bars([['在途请求结束', 503, '503 ms'], ['Shutdown 返回', 650, '650 ms']], 650, done=[0], mark=[1]), kv=KV([['新连接', '关闭监听后立刻 connection refused'], ['在途请求', '继续跑完,正常返回 200'], ['Shutdown 返回时间', '轮询间隔 1 ms 起翻倍,最长 500 ms']], ['Shutdown 返回时间'])),
    step("ctx 先到期(handler 1 s,Shutdown 的 ctx 只给 300 ms):Shutdown 在 404 ms 返回 context deadline exceeded,但它不会中止在途请求——不强制关闭时请求在 1002 ms 仍然完成 200;如果随后调用 srv.Close(),在途请求立刻失败(EOF,404 ms)。所以 Shutdown 超时之后要自己决定:继续等,还是 Close 强制断开。", t=tl(S(2)), mark=lidx(S(2), '强制 Close=true', '错误:EOF'), done=lidx(S(2), '强制 Close=false', '1002 ms 在途请求结束', '在途请求结束:200'), kv=KV([['ctx 到期', 'Shutdown 返回 deadline exceeded,请求不受影响'], ['srv.Close()', '强制断开,在途请求 EOF'], ['选择', '继续等 / 强制关,由你决定']], ['选择'])),
    step("长连接:一个流式 handler(先写 start,再等 Request.Context().Done())不会自己结束。没有通知时 Shutdown 等满 ctx 的 1.5 s,返回 context deadline exceeded(1605 ms),handler 直到连接被关才看到取消;用 BaseContext 给所有请求挂一个根 context,再 RegisterOnShutdown(cancelRoot):Shutdown 一调用 handler 就看到 context canceled(102 ms),Shutdown 在 104 ms 返回 nil。Shutdown 自己不会取消请求的 context。", t=tl(S(3)), mark=lidx(S(3), '通知 handler=false', '1605 ms'), done=lidx(S(3), '通知 handler=true', '102 ms'), b=bars([['没有通知:Shutdown 返回', 1605, '1605 ms(等到 ctx 到期)'], ['RegisterOnShutdown 通知:Shutdown 返回', 104, '104 ms']], 1605, mark=[0], done=[1]), kv=KV([['Shutdown', '不会取消请求的 context'], ['长连接', '会一直等到 ctx 到期'], ['解法', 'BaseContext + RegisterOnShutdown(cancel)']], ['解法'])),
    step("被 Hijack 的连接(WebSocket 等)不归 Shutdown 管:handler Hijack 之后,Shutdown 在 0 ms 就返回 nil,没有等它;随后客户端再读,是读超时(202 ms)而不是 EOF——连接仍然开着。要自己维护这类连接的列表,在收到关机通知时发关闭帧再断开。", t=tl(S(4)), mark=lidx(S(4), 'Shutdown 返回 err=<nil>', '被 Hijack 的连接仍然开着'), done=lidx(S(4), '客户端读到'), kv=KV([['Hijack 的连接', 'net/http 不再追踪'], ['Shutdown', '不等它,也不关它'], ['后果', '连接可能在进程退出时被粗暴断开']], ['后果'])),
    step("真实进程(客户端发一个 1 s 的请求,200 ms 时发 SIGTERM):A 只用 r.Run、没处理信号——进程在 2 ms 内被终止(退出码 -15,即被信号杀死),在途请求在 209 ms 得到 RemoteDisconnected(服务端没有给任何响应);B 用 signal.NotifyContext 接 SIGTERM、调用 srv.Shutdown(5 s):输出“收到信号,开始 Shutdown / Shutdown 完成,退出”,等了 1050 ms 才退出,退出码 0,在途请求拿到 slow done。", t=tl(S(5)), mark=lidx(S(5), '[plain]'), done=lidx(S(5), '[graceful]'), b=bars([['plain:SIGTERM 后进程退出', 2, '2 ms,退出码 -15'], ['graceful:SIGTERM 后进程退出', 1050, '1050 ms,退出码 0']], 1050, mark=[0], done=[1]), kv=KV([['plain', '被信号杀死,在途请求断开'], ['graceful', '等在途请求结束,退出码 0'], ['K8s 滚动更新', 'SIGTERM 之后默认给 30 秒,graceful 才不丢请求']], ['plain'])),
]
A = mkartn('n47', 47, 'Gin,优雅关机,Shutdown,SIGTERM,http.Server,Go,真实验证,动画演示',
    '在 Gin v1.12.0(配合 net/http)里实测优雅关机:Shutdown 立刻拒绝新连接、等在途请求,但返回时间会因轮询间隔晚最多约 500 ms;ctx 到期不会中止请求;长连接要用 BaseContext + RegisterOnShutdown 通知;被 Hijack 的连接不归它管;真实进程里 r.Run 收到 SIGTERM 在 2 ms 内被杀,优雅关机则等到在途请求结束。',
    'Gin 没有自带优雅关机,要靠标准库的 http.Server.Shutdown。它到底等多久、等什么、不等什么?ctx 超时了请求会不会被中断?长连接和 WebSocket 怎么办?这篇用进程内实验和真实的 SIGTERM 把每种情形都测一遍。',
    [('650 ms', '在途请求 503 ms 结束后 Shutdown 才返回(轮询间隔最长 500 ms)'), ('deadline exceeded', 'ctx 先到期时 Shutdown 的返回值,但在途请求仍然继续(1002 ms 才结束)'), ('2 ms vs 1050 ms', 'SIGTERM 之后进程退出的耗时:不处理信号 vs 优雅关机')],
    [('Shutdown 做了什么', '<p>先关闭所有监听(新连接立刻被拒绝),然后反复检查连接是否都已空闲,空闲的 keep-alive 连接会被关闭,正在处理请求的连接则等它们处理完。检查的间隔从 1 ms 开始翻倍、最长 500 ms,所以返回时间比最后一个请求结束可能晚最多半秒。</p>'),
     ('ctx 到期之后', '<p>Shutdown 的 ctx 只决定“等多久”:到期就返回 <code>context deadline exceeded</code>,但并不会终止在途请求。你必须决定接下来是继续等还是调用 <code>srv.Close()</code> 强制断开(在途请求会失败)。常见写法是给 Shutdown 一个略短于编排系统宽限期的 ctx(例如 K8s 的 30 秒),超时后 <code>Close</code>。</p>'),
     ('长连接', '<p>SSE、长轮询这样的 handler 不会因为 Shutdown 而结束,Shutdown 会一直等到 ctx 到期。办法是给 <code>http.Server</code> 设 <code>BaseContext</code> 返回一个你控制的根 context,再用 <code>RegisterOnShutdown</code> 在关机时取消它,handler 里监听 <code>Request.Context().Done()</code>(见 context 的几篇)。</p>'),
     ('被 Hijack 的连接', '<p>WebSocket 等被 <code>Hijack</code> 的连接完全不归 <code>Shutdown</code> 管:它既不等也不关。要自己维护这类连接的集合,收到关机通知时发关闭帧并断开,否则进程退出时它们会被粗暴地切断。</p>'),
     ('进程层面', '<p>只用 <code>r.Run</code>、不处理信号时,SIGTERM 会直接终止进程,在途请求丢失。用 <code>signal.NotifyContext</code> 接收 SIGTERM / SIGINT,收到后调用 <code>Shutdown</code>,再让 <code>main</code> 返回;注意 <code>ListenAndServe</code> 在 Shutdown 之后立刻返回 <code>http.ErrServerClosed</code>,不要在那里退出进程,要等 Shutdown 返回。</p>')],
    steps,
    [ENV_N_GIN + '。进程内的实验用真实的 net.Listen + http.Server(时间是相对进程内 t0 的毫秒数);第五节编译成真实二进制并用 Python 的 subprocess 启动、发 SIGTERM,客户端用 urllib;读过的 Go 源码:net/http/server.go 的 (*Server).Shutdown(pollIntervalBase 起始 1 ms、每次翻倍)与常量 shutdownPollIntervalMax = 500 * time.Millisecond(第 3227 行);每种情形各一次',
     '没有验证:Kubernetes 里 preStop、readiness 与 SIGTERM 的配合;HTTP/2 下 Shutdown 对 GOAWAY 的处理;TLS 连接的 Shutdown;Windows 上的信号;Shutdown 其余分支(h3 等)的细节;并发大量在途请求下的 Shutdown 耗时'],
    '优雅关机')
